int main(int argc,char**argv){SoDB::init();CoinRenderAction::initClass();CoinRenderOptions options;bool publicCpu=false;for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--recording"||a=="--public-cpu")publicCpu=true;else if(a=="--samples"&&i+1<argc){if(!unsignedOption(argv[++i],options.sampleCount))return 2;}else if(a=="--direct")options.sceneTexture=COIN_RENDER_SCENE_TEXTURE_DIRECT;else if(a=="--staged")options.sceneTexture=COIN_RENDER_SCENE_TEXTURE_STAGED;else if(a=="--portable-sampling")options.textureSamplingPolicy=COIN_RENDER_SAMPLING_PORTABLE;else return 2;}if(options.sampleCount!=1&&options.sampleCount!=2&&options.sampleCount!=4)return 2;CoinRenderCapabilities caps{};int query=coin_render_query_capabilities(COIN_RENDER_EXPERIMENTAL_OFFSCREEN,&caps,sizeof(caps));std::cout<<"cube_rtt_environment query="<<query<<" gpu="<<caps.gpu_available<<" backend="<<caps.backend<<" renderer="<<caps.renderer<<" adapter="<<caps.adapter_name<<" diagnostic="<<caps.diagnostic<<'\n';if(query!=0)return 1;if(publicCpu){if(!check(caps.backend==COIN_RENDER_EXPERIMENTAL_RECORDING&&!caps.gpu_available&&options.sampleCount==1&&options.sceneTexture==COIN_RENDER_SCENE_TEXTURE_STAGED,"explicit public CPU requires RECORDING/no GPU/STAGED/1x"))return 1;options.renderer=COIN_RENDER_RENDERER_UNKNOWN;}else{if(!caps.gpu_available)return 77;options.renderer=static_cast<CoinRenderRenderer>(caps.renderer);}std::unique_ptr<CoinRenderTarget>target(CoinRenderTarget::createOffscreen(SbVec2i32(side,side),options));if(!check(bool(target),"public target available"))return 1;if(publicCpu&&!check(target->getOptions().renderer==COIN_RENDER_RENDERER_UNKNOWN&&target->getOptions().sampleCount==1&&target->getOptions().sceneTexture==COIN_RENDER_SCENE_TEXTURE_STAGED,"public CPU target retains UNKNOWN/STAGED/1x options"))return 1;target->setDepthReadbackEnabled(TRUE);CoinRenderAction action(SbViewportRegion(side,side));action.setRenderTarget(target.get());action.setBackgroundColor(SbColor4f(0,0,0,0));action.setTransparencyType(CoinRenderAction::NONE);Scene scene;auto draw=[&](Frame&f,const char*phase){uint64_t before=target->getLastSubmissionSerial();action.apply(scene.root);target->readbackRGBA(f.rgba);target->readbackDepth(f.depth);f.serial=target->getLastSubmissionSerial();std::cout<<"cube_rtt_public phase="<<phase<<" status="<<action.getLastStatus()<<" serial="<<f.serial<<" error="<<action.getLastError().getString()<<'\n';return check(action.getLastStatus()==CoinRenderAction::SUCCESS&&f.serial>before&&f.rgba.size()==side*side*4&&f.depth.size()==side*side,phase);};Frame common,colored,changed,restored;bool ok=draw(common,"ordinary source/control first")&&centers(common,scene,false,"ordinary source/control first");if(ok){scene.enabled->whichChild=SO_SWITCH_ALL;ok &=draw(colored,"activate cube RTT")&&centers(colored,scene,true,"activate cube RTT");if(ok){scene.producer.paint(1);ok &=draw(changed,"cube producer mutation")&&centers(changed,scene,true,"cube producer mutation");scene.producer.paint(0);ok &=draw(restored,"cube producer recovery")&&centers(restored,scene,true,"cube producer recovery")&&exact(colored,restored);}}action.setRenderTarget(nullptr);return ok?0:1;}
